parameters.jsCode:
const body = $input.item.json.body || $input.item.json;

const userText = body.text || body.message || body.userPreference || "Looking for 10 marla house in Lahore";
let phone = String(body.phone || body.senderPhone || "923270831470").replace(/[^0-9]/g, "");
if (phone.startsWith("03")) phone = "92" + phone.substring(1);
const customerName = body.customerName || body.name || "Valued Client";

return [{
  json: {
    userText,
    phone,
    customerName,
    timestamp: new Date().toISOString()
  }
}];

