parameters.jsCode:
const rawContent = $input.item.json.choices?.[0]?.message?.content || "{}";
let params = {};
try {
  params = JSON.parse(rawContent);
} catch (e) {
  params = { sector: "property", city: "Lahore", budgetPKR: 0, keywords: [] };
}

const clientInfo = $('Extract User Inquiry').item.json;
const sector = (params.sector || "property").toLowerCase();
let recommendations = [];

if (sector.includes("furniture")) {
  recommendations = [
    {
      title: "Maharaja Royal Carved Bed Set",
      price: "PKR 345,000",
      wood: "Pure Solid Sheesham",
      specs: "King Size, 2 Side Tables, Dressing Table, 10-Yr Warranty",
      link: "https://watechsolutions.com/marketplace/furniture/royal-bed-01"
    },
    {
      title: "Hand-Carved Floral 7-Seater Sofa Suite",
      price: "PKR 285,000",
      wood: "Solid Sheesham with Imported Velvet",
      specs: "3+2+2 Setup, Crown Carving, MoltyFoam High Density",
      link: "https://watechsolutions.com/marketplace/furniture/floral-sofa-07"
    },
    {
      title: "Antique Solid Teak 8-Seater Dining Suite",
      price: "PKR 395,000",
      wood: "Export Seasoned Teak Wood",
      specs: "8 Cushioned Carved Chairs + Glass Top Dining Table",
      link: "https://watechsolutions.com/marketplace/furniture/teak-dining-08"
    }
  ];
} else if (sector.includes("event") || sector.includes("catering")) {
  recommendations = [
    {
      title: "Grand Crystal Ballroom (Royal Palm Lahore)",
      price: "PKR 3,800 per head",
      specs: "Capacity: 300 - 800 guests, AC Hall, Stage Decor & Lighting Included",
      link: "https://watechsolutions.com/marketplace/events/royal-palm-crystal"
    },
    {
      title: "Margalla View Luxury Marquee (Islamabad)",
      price: "PKR 4,500 per head",
      specs: "Capacity: 500 - 1200 guests, VIP Lounge, Continental + Desi Menu",
      link: "https://watechsolutions.com/marketplace/events/margalla-view-isb"
    },
    {
      title: "Creek Heritage Live BBQ Lawn (Karachi)",
      price: "PKR 3,200 per head",
      specs: "Capacity: 250 - 600 guests, Open Air Seaside Ambience, Live BBQ Counters",
      link: "https://watechsolutions.com/marketplace/events/creek-heritage-khi"
    }
  ];
} else {
  // Default Real Estate Recommendations
  recommendations = [
    {
      title: "10 Marla Brand New Modern Luxury Villa",
      price: "PKR 4.2 Crore",
      specs: "5 Bed with Attached Bath, Double Height Lobby, Bahria Town",
      link: "https://watechsolutions.com/marketplace/properties/10-marla-villa-bahria"
    },
    {
      title: "1 Kanal Ultra-Luxury Designer Mansion",
      price: "PKR 8.5 Crore",
      specs: "6 Master Beds, Swimming Pool, Basement, DHA Phase 6 Lahore",
      link: "https://watechsolutions.com/marketplace/properties/1-kanal-dha-phase-6"
    },
    {
      title: "5 Marla Prime Location Ready-to-Build Plot",
      price: "PKR 95 Lac",
      specs: "Direct Possession, Near Commercial Hub & Park, Bahria Phase 8",
      link: "https://watechsolutions.com/marketplace/properties/5-marla-bahria-ph8"
    }
  ];
}

let messageBody = `Assalam-o-Alaikum *${clientInfo.customerName}*! 🌟\n\nAap ki inquiry ke mutabiq Watech AI ne hamare verified database se top 3 matched recommendations select ki hain:\n\n`;

recommendations.forEach((item, index) => {
  messageBody += `*${index + 1}. ${item.title}*\n`;
  messageBody += `💰 *Price:* ${item.price}\n`;
  messageBody += `📋 *Specs:* ${item.specs}\n`;
  if (item.wood) messageBody += `🪵 *Wood:* ${item.wood}\n`;
  messageBody += `🔗 *View Details:* ${item.link}\n\n`;
});

messageBody += `Agar aap in mein se kisi ka site visit schedule karna chahte hain ya custom quotation chahte hain to is message ka reply karein ya call karein: 0327-0831470.`;

return [{
  json: {
    phone: clientInfo.phone,
    customerName: clientInfo.customerName,
    sector,
    formattedMessage: messageBody,
    recommendationsCount: recommendations.length
  }
}];
